// shift captures the rest of the computation as k: add 1 to the supplied value.
// k(2) returns 3. The handler multiplies it by 10, so reset returns 30.

console.log(reset(() => 1 + shift(k => k(2) * 10)));

// stop discards the remaining computation up to the nearest reset and returns 7.
// The two calls compare how much is discarded with and without the inner reset.
function stop() {
  return shift(() => 7);
}

console.log(reset(() => 100 + reset(() => 10 + stop())));
console.log(reset(() => 100 + 10 + stop()));

// The handler returns 42 without calling k, so the rest of the reset body is skipped.
// The reset expression returns 42.

console.log(reset(() => {
  const value = shift(k => 42);
  console.log("Unreachable");
  return value + 1;
}));

// The numbered log messages trace the execution order. k(2) resumes at the shift expression.
// When the resumed computation reaches the end of the reset body,
// its result goes back to the shift handler.

console.log("1. Before reset");
const result = reset(() => {
  console.log("2. Before shift");
  const value = shift(k => {
    console.log("3. In the shift handler before resuming");
    const resumed = k(2);
    console.log("5. Back in the shift handler:", resumed);
    return resumed * 10;
  });
  console.log("4. In the resumed computation:", value);
  return value + 1;
});
console.log("6. Final result:", result);

// Returning the captured continuation k from reset allows calling it repeatedly later.

const k = reset(() => 10 + shift(k => k));
console.log(k(2));
console.log(k(5));

// The handler resumes the same continuation with 2 and again with 3.
// It adds (1 + 2) and (1 + 3), giving 7.

console.log(reset(() => 1 + shift(k => k(2) + k(3))));

// Each resumption shares the count variable created before capture.
// Every call to next increments it.

const next = reset(() => {
  let count = 0;
  shift(k => k);
  return ++count;
});
console.log(next(), next(), next());

// A resumed computation can call shift again. Resuming first yields a new
// continuation each time. The resulting continuations a and b can be resumed separately.

const first = reset(() => {
  function inner() {
    return shift(k => k) + shift(k => k);
  }
  return 10 + inner();
});
const a = first(2);
const b = first(5);
console.log(a(3), b(4), a(9));

// choose uses shift to try every pair of candidates,
// and the body prints each pair that adds up to 10.

function choose(items) {
  return shift(k => {
    for (const item of items) k(item);
  });
}

reset(() => {
  const x = choose([2, 4, 7]);
  const y = choose([3, 6, 8]);
  if (x + y === 10) {
    console.log(`${x} + ${y} = 10`);
  }
});

// choose resumes the computation for each candidate. guard drops a failed branch.
// place creates a new board per branch. Changes to shared objects are not rolled back.
function choose(values) {
  return shift(k => {
    for (let i = 0; i < values.length; i++) k(values[i]);
  });
}

function guard(condition) {
  if (!condition) shift(k => undefined);
}

function place(columns) {
  if (columns.length === 4) {
    console.log(JSON.stringify(columns));
    return;
  }
  const column = choose([0, 1, 2, 3]);
  const row = columns.length;
  for (let previous = 0; previous < row; previous++) {
    guard(columns[previous] !== column);
    guard(Math.abs(columns[previous] - column) !== row - previous);
  }
  place(columns.concat([column]));
}

// Array indices are rows and values are columns. Both start at zero.
reset(() => place([]));

// visitLeaves walks the tree recursively and suspends at each leaf.
// sameFringe advances the two walks one leaf at a time and compares their values.
function visitLeaves(tree, side) {
  if (Array.isArray(tree)) {
    visitLeaves(tree[0], side);
    visitLeaves(tree[1], side);
    return;
  }

  console.log(side + ": " + tree);
  shift(resume => ({ value: tree, resume }));
}

function sameFringe(left, right) {
  let leftStep = reset(() => visitLeaves(left, "left"));
  let rightStep = reset(() => visitLeaves(right, "right"));

  while (leftStep !== undefined && rightStep !== undefined) {
    if (leftStep.value !== rightStep.value) return false;
    leftStep = leftStep.resume();
    rightStep = rightStep.resume();
  }

  return leftStep === undefined && rightStep === undefined;
}

console.log(sameFringe([[1, 2], 3], [1, [2, 3]]));
console.log(sameFringe([[1, 2], 3], [1, [9, 3]]));

// flip evaluates both heads and tails. An event returns 1 on branches where it occurs
// and 0 elsewhere, so the weighted sum gives its probability.
function flip(p) {
  return shift(resume => p * resume(true) + (1 - p) * resume(false));
}

function probabilityOf(event) {
  return reset(() => {
    const firstHeads = flip(0.25);
    const secondHeads = flip(0.75);
    return event(firstHeads, secondHeads) ? 1 : 0;
  });
}

const exactlyOneHead = probabilityOf((first, second) => first !== second);
const onlyFirstHead = probabilityOf((first, second) => first && !second);

console.log("P(exactly one head):", exactlyOneHead);
console.log("P(first is heads | exactly one head):", onlyFirstHead / exactlyOneHead);

// callCC passes a function that jumps to the captured continuation.
// Calling it discards the rest of the caller’s computation.
function callCC(f) {
  return shift(k =>
    k(f(value => shift(ignored => k(value))))
  );
}

// This reset bounds the entire example. There is no inner reset,
// so callCC captures the rest of the computation up to this boundary.
reset(() => {
  // If the continuation is not called, the callback returns normally.
  const normal = callCC(k => 7);
  console.log("Normal return:", normal);

  // Even a deeply nested call can jump back to the callCC expression with a value.
  const found = callCC(exit => {
    function search() {
      for (let i = 1; i <= 10; i++) {
        if (i * i > 20) exit(i);
      }
    }
    search();
    console.log("Unreachable after the jump");
    return -1;
  });
  console.log("Search result:", found);

  let saved;
  let jumps = 0;
  const value = callCC(k => {
    saved = k;
    return 10;
  });

  // saved captures everything from this point to the end of the reset.
  // The jumps counter is not rolled back. The code jumps to the same continuation twice.
  console.log("Value at resumption:", value);
  if (jumps < 2) {
    jumps++;
    saved(value + 10);
    console.log("The jump does not return here");
  }
  console.log("End of program");
});

// perform returns a request containing an operation, its argument, and a continuation.
// handle interprets the request and resumes it, so program does not need to know where state lives.
// The same handler processes later requests. This example runs synchronously.
// Unknown operations throw. The example has no outer or composed handlers.
function perform(operation, argument) {
  return shift(resume => ({ kind: "effect", operation, argument, resume }));
}

function handle(program, initialState) {
  let state = initialState;
  const logs = [];
  let step = reset(() => ({ kind: "done", value: program() }));
  while (step.kind === "effect") {
    let response;
    switch (step.operation) {
      case "get":
        response = state;
        break;
      case "put":
        state = step.argument;
        break;
      case "log":
        logs.push(step.argument);
        break;
      default:
        throw new Error("Unhandled operation: " + step.operation);
    }
    step = step.resume(response);
  }
  return { value: step.value, state, logs };
}

function program() {
  const before = perform("get");
  perform("put", before + 1);
  const after = perform("get");
  perform("log", `${before} → ${after}`);
  return after * 2;
}

// The same computation is interpreted with two different initial states.
console.log(JSON.stringify(handle(program, 0)));
console.log(JSON.stringify(handle(program, 10)));
